    },
    {
      "name": "frontend-design",
      "source": {
        "source": "git-subdir",
        "url": "https://github.com/anthropics/claude-plugins-official.git",
        "path": "plugins/frontend-design"
      },
      "description": "Optional external dependency (official Anthropic). Design guidance for the frontend architects (react, vue, angular, react-native, inertia-*). Raw generation converges on generic AI aesthetics regardless of model tier — this is the fix for that, not a bigger model. Pipeline runs without it."
    },
    {
      "name": "sdlc",
      "source": "./plugins/sdlc",
      "description": "Universal SDLC orchestrator with auto-discovery of stack providers. Provides pipeline-orchestrator skill plus 5 cost-tiered default agents (BA Opus/high, Dev Sonnet/medium, QA Sonnet/medium, Sec Opus/high, Docs Haiku/low). Slash commands: /sdlc:start, /sdlc:batch, /sdlc:doctor, /sdlc:list-stacks, /sdlc:security-init."
    },
    {
      "name": "js-foundation",
      "source": "./plugins/js-foundation",
      "description": "Shared JavaScript/TypeScript foundation skills (typescript-patterns + npm-patterns). No agent, no stack profile. Referenced cross-plugin by every JS/TS framework provider in the marketplace."
    },
    {
      "name": "nodejs-plugin",
      "source": "./plugins/nodejs-plugin",
      "description": "Node.js backend stack provider for Express/Fastify/Koa/plain Node.js projects. Adds node-architect agent (Sonnet/medium) and node-conventions skill. Reuses TypeScript and npm skills from js-foundation. Composes with frontend plugins via aspect resolution."
    },
    {
      "name": "nestjs-plugin",
      "source": "./plugins/nestjs-plugin",
      "description": "NestJS opinionated backend stack provider. Adds nest-architect agent (Sonnet/medium) covering REST + ORM (TypeORM/Prisma/Mongoose) + GraphQL + WebSockets + Microservices. Reuses TypeScript and npm skills from js-foundation."
    },
    {
      "name": "nextjs-plugin",
      "source": "./plugins/nextjs-plugin",
      "description": "Next.js full-stack React framework. Multi-aspect ownership (backend + frontend, priority=250). App Router, Server Components, Server Actions, Route Handlers, ISR/SSG/SSR. Adds nextjs-architect agent (Sonnet/medium). Reuses TypeScript and npm skills from js-foundation."
    },
    {
      "name": "react-plugin",
      "source": "./plugins/react-plugin",
      "description": "React SPA frontend stack provider (priority=150). Components, hooks, state management, routing, react-hook-form, RTL+Vitest+Playwright. Adds react-architect agent (Sonnet/medium). Composes with backend plugins via aspect resolution."
    },
    {
      "name": "vue-plugin",
      "source": "./plugins/vue-plugin",
      "description": "Vue 3 SPA frontend stack provider (priority=150). Composition API, Pinia, Vue Router v4, vee-validate + zod, Vitest + @vue/test-utils. Adds vue-architect agent (Sonnet/medium). Vue 3 primary; Vue 2 fallback notes."
    },
    {
      "name": "angular-plugin",
      "source": "./plugins/angular-plugin",
      "description": "Angular 18-21 SPA frontend stack provider (priority=200). Standalone + NgModule equally, signals + NgRx, typed Reactive Forms, Angular Router. Adds angular-architect agent (Sonnet/medium). Reuses TypeScript and npm skills from js-foundation."
    },
    {
      "name": "react-native-plugin",
      "source": "./plugins/react-native-plugin",
      "description": "React Native mobile stack provider (priority=300). Both Expo (managed/dev-client/EAS) and bare workflows. React Navigation v7 + Expo Router, AsyncStorage/MMKV, Jest + RTL Native. Adds rn-architect agent (Sonnet/medium). Wins over react-plugin on RN projects."
    },
    {
      "name": "php-foundation",
      "source": "./plugins/php-foundation",
      "description": "Shared PHP foundation skills for the SDLC marketplace. Contains stack-agnostic PHP conventions (php-conventions — readonly properties, enums, match, constructor promotion, strict_types, PSR-12), composer-tooling (PSR-4 autoloading, version constraints, scripts, platform requirements), and php-testing (PHPUnit + Pest structure, data providers, test doubles, fixtures, coverage). No agent, no stack profile — pure shared library. Referenced by laravel-plugin and symfony-plugin."
    },
    {
      "name": "laravel-plugin",
      "source": "./plugins/laravel-plugin",
      "description": "Laravel backend + database stack provider (priority=100). Registers Laravel profile via stack.md; provides laravel-architect (Sonnet/medium, backend-only) and artisan-specialist (Sonnet/low) agents plus laravel-conventions and eloquent-patterns skills. Reuses php-foundation skills. Extra database phase after development. Laravel Boost MCP integration when wired. Pairs with inertia-vue-plugin or inertia-react-plugin for Inertia frontends."
    },
    {
      "name": "symfony-plugin",
      "source": "./plugins/symfony-plugin",
      "description": "Symfony backend + database stack provider (priority=100). Detects symfony/framework-bundle in composer.json. Provides symfony-architect (Sonnet/medium — attribute routing, controllers-as-services, DI, Form types, validation, Voters, Serializer, Messenger, Twig) and doctrine-specialist (Sonnet/low — entity mappings, generated migrations, fixtures, schema verification) agents plus symfony-conventions and doctrine-patterns skills. Reuses php-foundation skills. Extra database phase after development. Renders Twig views and designs the Serializer/API contract for SPA frontend plugins (vue/react)."
    },
    {
      "name": "inertia-vue-plugin",
      "source": "./plugins/inertia-vue-plugin",
      "description": "Inertia.js + Vue 3 frontend stack provider (priority=175). Pairs with laravel-plugin for full-stack Laravel+Inertia projects. Detects @inertiajs/vue3 adapter. Adds inertia-vue-architect agent (Sonnet/medium). Beats generic vue-plugin (150) for the frontend aspect. Server-driven Inertia pages — no client-side Vue Router."
    },
    {
      "name": "inertia-react-plugin",
      "source": "./plugins/inertia-react-plugin",
      "description": "Inertia.js + React frontend stack provider (priority=175). Pairs with laravel-plugin for full-stack Laravel+Inertia+React projects. Detects @inertiajs/react adapter. Adds inertia-react-architect agent (Sonnet/medium). Beats generic react-plugin (150) for the frontend aspect. Server-driven Inertia pages — no React Router."
    },
    {
      "name": "csharp-foundation",
      "source": "./plugins/csharp-foundation",
      "description": "Shared C#/.NET foundation skills for the SDLC marketplace. Contains stack-agnostic C# conventions (csharp-conventions — nullable reference types, records, pattern matching, async/await + CancellationToken, IDisposable, naming), dotnet-tooling (dotnet CLI, NuGet PackageReference, central package management, Directory.Build.props, dotnet format), and dotnet-testing (xUnit [Fact]/[Theory], Moq/NSubstitute, FluentAssertions, coverlet coverage). No agent, no stack profile — pure shared library. Referenced by aspnet-core-plugin."
    },
    {
      "name": "aspnet-core-plugin",
      "source": "./plugins/aspnet-core-plugin",
      "description": "ASP.NET Core backend + database stack provider (priority=100). Detects projects via appsettings.json. Provides aspnet-core-architect (Sonnet/medium — Minimal API / MVC controllers, DTOs, FluentValidation, DI, Options pattern, authorization policies, HTTPS/HSTS, EF Core entity stubs, Program.cs composition) and efcore-specialist (Sonnet/low — entity Fluent API configuration, column types, indexes, unique constraints, cascade rules, migration generation and verification) agents plus aspnet-conventions and efcore-patterns skills. Reuses csharp-foundation skills. Extra database phase after development. Designs the API contract for SPA frontend plugins (vue/react)."
    },
    {
      "name": "java-foundation",
      "source": "./plugins/java-foundation",
      "description": "Shared Java foundation skills for the SDLC marketplace. Contains stack-agnostic Java conventions (java-conventions — records, sealed types, Optional, streams), build-tooling (Maven/Gradle wrapper, BOM dependency management), and jvm-testing (JUnit 5, Mockito, AssertJ, Testcontainers). No agent, no stack profile — pure shared library. Referenced by java-plugin and spring-boot-plugin."
    },
    {
      "name": "java-plugin",
      "source": "./plugins/java-plugin",
      "description": "Plain Java backend stack provider (priority=100). Detects any Maven or Gradle project (pom.xml / build.gradle / build.gradle.kts). Adds java-architect agent (Sonnet/medium) for plain Java libraries, CLI tools, and micro-services without a recognized web framework. Falls back gracefully when spring-boot-plugin (priority 150) matches instead. Reuses java-foundation skills."
    },
    {
      "name": "spring-boot-plugin",
      "source": "./plugins/spring-boot-plugin",
      "description": "Spring Boot backend stack provider (priority=150). Detects Spring Boot projects via spring-boot marker in any build file. Adds spring-boot-architect agent (Sonnet/medium) covering REST controllers, Spring Data JPA, Bean Validation, Spring Security, Flyway/Liquibase migrations, and @SpringBootTest/@WebMvcTest/@DataJpaTest test slices. Beats java-plugin (100) on the backend aspect for Spring projects. Reuses java-foundation skills."
    },
    {
      "name": "python-foundation",
      "source": "./plugins/python-foundation",
      "description": "Shared Python foundation skills for the SDLC marketplace. Contains stack-agnostic Python conventions (python-conventions — type hints, dataclasses, match, pathlib, enums, context managers, PEP 8, strict typing), python-tooling (pyproject.toml as source of truth, pip/Poetry/uv/pipenv, venv, lockfiles, ruff lint+format, mypy, console scripts), and pytest-testing (fixtures, parametrize, conftest, monkeypatch, unittest.mock, pytest-cov). No agent, no stack profile — pure shared library. Referenced by django-plugin, fastapi-plugin, flask-plugin, and python-plugin."
    },
    {
      "name": "python-plugin",
      "source": "./plugins/python-plugin",
      "description": "Plain Python backend stack provider (priority=100). Detects any Python project via pyproject.toml/requirements.txt/setup.py/Pipfile. Adds python-architect agent (Sonnet/medium) for libraries, CLI tools, scripts, data pipelines, and microservices without a recognized web framework. Falls back gracefully when django-plugin/fastapi-plugin/flask-plugin (priority 150) match instead. Adds python-app-conventions skill. Reuses python-foundation skills."
    },
    {
      "name": "django-plugin",
      "source": "./plugins/django-plugin",
      "description": "Django backend + database stack provider (priority=150). Detects manage.py or Django in pyproject.toml/requirements.txt. Provides django-architect (Sonnet/medium — views, DRF ViewSets, serializers, forms, URLconf, middleware, signals, model definitions, Django templates, DRF API contract for SPA frontends) and django-migrations-specialist (Sonnet/low — model field finalization, indexes/constraints, makemigrations, sqlmigrate review, migrate, verify) agents plus django-conventions and django-orm-patterns skills. Reuses python-foundation skills. Extra database phase after development."
    },
    {
      "name": "fastapi-plugin",
      "source": "./plugins/fastapi-plugin",
      "description": "FastAPI backend + database stack provider (priority=150). Detects fastapi in pyproject.toml/requirements.txt. Provides fastapi-architect (Sonnet/medium — APIRouter, Pydantic v2 schemas, Depends injection, async endpoints, OAuth2/JWT, OpenAPI, SQLAlchemy model stubs, API contract for SPA frontends) and alembic-specialist (Sonnet/low — SQLAlchemy 2.0 mapped classes, alembic revision --autogenerate, migration review, alembic upgrade head, verification) agents plus fastapi-conventions and sqlalchemy-patterns skills. Reuses python-foundation skills. Extra database phase after development."
    },
    {
      "name": "flask-plugin",
      "source": "./plugins/flask-plugin",
      "description": "Flask backend + database stack provider (priority=150). Detects Flask in pyproject.toml/requirements.txt. Provides flask-architect (Sonnet/medium — app factory, Blueprints, views, Flask-Login/JWT auth, Jinja2 templates or JSON API, Marshmallow/WTForms, SQLAlchemy model definitions) and flask-migrate-specialist (Sonnet/low — Flask-Migrate: flask db migrate, SQL review, flask db upgrade, flask db check) agents plus flask-conventions and sqlalchemy-patterns skills. Reuses python-foundation skills. Extra database phase after development."
    }
  ]
}

