man:performance-dudes/ai-plugins:
{
  "name": "ai-plugins",
  "description": "Performance Dudes — public Claude Code plugins (signing, workspace infrastructure) and reference examples.",
  "owner": {
    "name": "Performance Dudes"
  },
  "plugins": [
    {
      "name": "example",
      "source": "./plugins/example",
      "description": "Reference showcase of every Claude Code plugin component and technique — workflow, command, skill (calling the workflow), subagent, theme, output style, plus .example templates for hooks/MCP/LSP/monitors and a tests/ folder on how to test plugins and skills. Command: /greet",
      "version": "0.2.0"
    },
    {
      "name": "context-aware",
      "source": "./plugins/context-aware",
      "description": "Reference plugin for building context-aware plugins: workflows and agents that route ALL retrieval through the context-mode MCP (ctx_*), so raw bytes are indexed and searched in a sandbox, never dumped into the window. Requires context-mode (enabled once at the workspace level). Teaches the five patterns (index-once-slice-many, fetch-and-index, plain-JS glue, structured-output handoffs, lean orchestrator) and ships a runnable, domain-agnostic demo. Command: /context-aware",
      "version": "0.1.1"
    },
    {
      "name": "transcribe",
      "source": "./plugins/transcribe",
      "description": "Quality-first multi-speaker transcription on Apple Silicon — an on-device ffmpeg/Whisper/pyannote pipeline plus parallel Opus deliverables (verbatim clean transcript, minutes, quoted facts, personas, todos). Generic: all domain knowledge comes from user-provided context. Command: /transcribe",
      "version": "0.1.2"
    },
    {
      "name": "ocr",
      "source": "./plugins/ocr",
      "description": "Quality-first OCR + auto-classification of scanned documents on Apple Silicon — on-device Apple Vision OCR (auge, auto-rotating) plus parallel Opus classification into a reviewable rename/sort proposal, with a separate dry-run apply step (undo log, searchable PDF text layers). Generic: all domain knowledge comes from user-provided context. Command: /ocr",
      "version": "0.1.3"
    },
    {
      "name": "image-toolkit",
      "source": "./plugins/image-toolkit",
      "description": "Image create & edit framework — Google Gemini for AI generation and semantic editing (recommended path), plus ImageMagick 7 for fast local processing (resize, crop, convert, watermark, favicon, batch, GIF, montage). Bundled generate_image.py runs via uv (no manual deps). Generic: prompts and assets come from the user. Command: /image",
      "version": "0.1.1"
    },
    {
      "name": "content-craft",
      "source": "./plugins/content-craft",
      "description": "Research-backed content & design craft — two generic user-space skills: blog-article-writing (AIDA/PAS frameworks, headline patterns, readability, editing checklist) and design-skills-2026 (WCAG 2.1 AA, Core Web Vitals, mobile-first responsive UI, typography, motion, onboarding UI patterns). Generic, evidence-based — no PD IP. Conversion-/PLG-psychology lives in the sales plugin.",
      "version": "0.1.0"
    },
    {
      "name": "mechanic",
      "source": "./plugins/mechanic",
      "description": "Cost-tiered mechanical subagents — two agents pinned to cheaper model versions so the premium tier (Opus / Sonnet 5) stays reserved for judgment. `mechanic` (Sonnet 4.6) for mechanical work that needs code/context comprehension (specified edits, cross-file refactors, boilerplate that must fit); `errand` (Haiku 4.5) for trivial self-contained transformations that need no codebase understanding (classify, extract, reformat, literal find/replace). Routing: needs code understanding -> mechanic; needs a decision -> general-purpose; otherwise -> errand. Invoke via the Agent tool with subagent_type \"mechanic\" or \"mechanic:errand\".",
      "version": "0.5.1"
    }
  ]
}

