man:SlashyIsTaken/fp-pluginplaza:
{
  "$schema": "https://anthropic.com/claude-code/marketplace.schema.json",
  "name": "flarepoint",
  "description": "Flarepoint Plugin Plaza (fp) — a plaza of small, behavioural Claude Code plugins that surface the AI's state or shape how it approaches a task, intervening only at the edges, never steering it mid-reason. Built on one shared substrate (fp-base). https://github.com/SlashyIsTaken/fp-pluginplaza",
  "owner": {
    "name": "Flarepoint",
    "url": "https://github.com/SlashyIsTaken"
  },
  "plugins": [
    {
      "name": "fp-honesty",
      "source": "./plugins/fp-honesty",
      "description": "Annotate load-bearing claims with their epistemic basis (verified/inferred/recalled/guess) and a per-response footer tally. Pure annotation — never changes what the model does.",
      "category": "productivity"
    },
    {
      "name": "fp-barbeque",
      "source": "./plugins/fp-barbeque",
      "description": "Understanding-first mode. On exploratory tasks (refactors, design, ambiguous scope) the model grills you toward mutual understanding before writing code, so you can debug and own the result. Sets a prior at the task edge and skips trivial work; never steers mid-solve. Modes: off, on (default).",
      "category": "productivity"
    },
    {
      "name": "fp-minify",
      "source": "./plugins/fp-minify",
      "description": "Comment-concision mode. Shapes the code the model writes so comments earn their place — a non-obvious why, or meaning a name can't hold (config, units, constraints) — and stay short; deep backstory goes to the commit. API docstrings are exempt. Sets a prior at the task edge; only ever touches comments, never behavior. Modes: off, new, tidy (default). Plus /fp-minify:strip for deliberate bulk de-commenting.",
      "category": "productivity"
    },
    {
      "name": "fp-sicem",
      "source": "./plugins/fp-sicem",
      "description": "Readable-prose mode (\"sic 'em-dash\"). In the prose the model writes (READMEs, docs, markdown, PR and commit bodies) it defaults the em-dash out of existence, replacing it and its cousins (semicolon, colon-as-drama, long dash-parentheticals) with clear connectors that read well for every English reader, non-native ones included. Clearer and cleaner, never dumbed down. Prose artifacts only; not chat, not code, not code comments (fp-minify's turf). Sets a prior at the task edge; never steers mid-solve. Modes: off, on (default).",
      "category": "productivity"
    }
  ]
}

