      "version": "1.1.0"
    },
    {
      "name": "time-registration",
      "source": "./plugins/time-registration",
      "description": "Git-based time registration summaries",
      "version": "1.3.1"
    },
    {
      "name": "lottie-animator",
      "source": "./plugins/lottie-animator",
      "description": "Generate professional Lottie animations from static SVGs. Replaces After Effects for motion graphics.",
      "version": "1.1.0"
    },
    {
      "name": "react-query",
      "source": "./plugins/react-query",
      "description": "TanStack Query v5 skill with three modes — code review, v4→v5 migration, and coding guidance for new v5 code. Grounded in the official v5 docs.",
      "version": "2.0.0"
    },
    {
      "name": "driverjs-guide",
      "source": "./plugins/driverjs-guide",
      "description": "Driver.js product tours, onboarding flows, and element highlighting reference",
      "version": "1.1.0"
    },
    {
      "name": "cofounder",
      "source": "./plugins/cofounder",
      "description": "Critical-thinking business co-founder that enforces prioritization, challenges assumptions, and becomes smarter over time",
      "version": "1.2.0"
    },
    {
      "name": "pm",
      "source": "./plugins/pm",
      "description": "Delivery-focused project manager that enforces deadlines, tracks estimates, detects drift, and holds you accountable",
      "version": "2.0.1"
    },
    {
      "name": "use-agentvision",
      "source": "./plugins/use-agentvision",
      "description": "See and interact with the user's screen using Agent Vision — screenshots, element discovery, clicks, form filling, and visual QA",
      "version": "1.2.0"
    },
    {
      "name": "cpr",
      "source": "./plugins/cpr",
      "description": "Commit, Push, and Release — one-command workflow with release-please integration",
      "version": "1.2.0"
    },
    {
      "name": "open-markdown",
      "source": "./plugins/open-markdown",
      "description": "Offer to open markdown documents (plans, specs, design docs) in mdreader for comfortable reading",
      "version": "1.1.0"
    },
    {
      "name": "cloudflare-deploy",
      "source": "./plugins/cloudflare-deploy",
      "description": "Deploy Astro sites to Cloudflare Workers with custom domains — setup, wrangler config, DNS, and deployment verification",
      "version": "0.1.0"
    },
    {
      "name": "drill-me",
      "source": "./plugins/drill-me",
      "description": "Stress-test a plan before implementation by walking the design tree one decision at a time, with a recommended answer for every question",
      "version": "0.1.0"
    },
    {
      "name": "comment-conventions",
      "source": "./plugins/comment-conventions",
      "description": "Language-agnostic code commenting and docblock conventions — present-tense comments, dev-focused content, mandatory docblocks on new functions/methods/components, a 3-source-line descending-length cap on docblock prose, and a no-chatter rule for inline comments (no prose walls, no business-logic essays, no step-by-step narration in the code path). Auto-fixes non-compliant docblocks and inline-comment walls on existing functions in the file being edited, leaving unusually long deliberate docblocks alone. Ships a PostToolUse hook that auto-validates Rule 4 on every Edit/Write.",
      "version": "0.8.0"
    },
    {
      "name": "design-principles",
      "source": "./plugins/design-principles",
      "description": "Apple's eight core principles of design (Purpose, Agency, Responsibility, Familiarity, Flexibility, Simplicity, Craft, Delight) as a working framework for reviewing, critiquing, and building user interfaces — applied with the canonical examples and with trade-offs surfaced whenever honoring one principle costs another",
      "version": "0.1.0"
    },
    {
      "name": "disk-cleanup",
      "source": "./plugins/disk-cleanup",
      "description": "Multi-step macOS disk-space cleanup: identify what's using disk, propose a safety-tiered plan, then execute with confirmation. Covers caches, dev tooling, VMs, Ollama models, orphaned app data, app uninstalls, and the Time Machine local-snapshot trap",
      "version": "0.1.0"
    }
  ]
}

