man:jslizar/virio-marketplace-handoff:
{
  "name": "jslizar-marketplace",
  "owner": {
    "name": "Jacob Lizarraga"
  },
  "plugins": [
    {
      "name": "content-engine",
      "source": "./plugins/content-engine",
      "description": "Unified LinkedIn + X content engine: one pipeline for ABM, TOFU, MOFU, and BOFU posts, pulling viral formats from selectable libraries (Virio corpus, Millie's curated list, and the weekly Emerging scan \u2014 multi-select, pooled). Resolves named clients via Virio first. Pick a winning draft and it generates a paste-ready Claude graphic prompt. Library auto-refreshes and self-heals each run. Also mines LinkedIn and X creator strategies (/content-engine:creators, /content-engine:x-creators). Requires the Virio MCP connector.",
      "version": "0.12.0"
    },
    {
      "name": "copy-post",
      "source": "./plugins/copy-post",
      "description": "Style-matching engine: reverse-engineers an example LinkedIn post into a reusable style spec, then drafts a style-matched, funnel-classified, ICP-personalized, de-slopped post. Complements content-engine (library-driven) with example-driven drafting.",
      "version": "0.4.0"
    },
    {
      "name": "watt",
      "source": "./plugins/watt",
      "description": "Watt voice, brand, and signal-story toolkit: draft and de-slop copy in the founder voice (/deslop, /post), apply the Watt design system, and turn Watt audience data into branded signal-story reports. Merges the former watt-voice, watt-design, and watt-signal-story plugins.",
      "version": "1.0.0"
    },
    {
      "name": "gtm-strategy-suite",
      "source": "./plugins/gtm-strategy-suite",
      "description": "Builds a rigorous client-ready GTM strategy doc from a 16-section master template, delegating segmentation, pricing economics, sales-motion math, conjoint analysis, benchmarks, and claims-grounding to specialist skills with deterministic Python calculators.",
      "version": "0.1.0"
    },
    {
      "name": "dm-master",
      "source": "./plugins/dm-master",
      "description": "LinkedIn outreach ghostwriting: profile analysis, tone read, and register-matched connection notes, DMs, follow-ups, call asks, and rejection comebacks \u2014 written as the client, never inventing a profile detail.",
      "version": "1.0.0"
    },
    {
      "name": "lets-get-curious",
      "source": "./plugins/lets-get-curious",
      "description": "Turns a topic you have to post about but don't care about into one you're curious enough to write well: 11 curiosity lenses, angle triage, then verified surprising facts. Hands off to watt or dm-master for drafting.",
      "version": "1.0.0"
    },
    {
      "name": "content-interview",
      "source": "./plugins/content-interview",
      "description": "Client content-intake pipeline: prep an interview by researching the FOC in Virio (strategy, tone, ICPs, banned topics), the account's Notion context (past meetings, content pillars, strategy docs), and their recent posts, run the tailored interview, build a deep emotional ICP avatar, mine the transcript into 20+ tagged post concepts, and draft to hook-lever writing standards. Feeds content-engine downstream; Virio + Notion connectors recommended, works without them.",
      "version": "1.2.0"
    },
    {
      "name": "linkedin-strategy",
      "source": "./plugins/linkedin-strategy",
      "description": "LinkedIn performance advisor grounded in research on 226K posts: performance states, image and timing strategy, reaction mechanics, topic selection, and 2026 feed mechanics \u2014 answers 'why is my engagement down' with findings, not vibes.",
      "version": "1.0.0"
    },
    {
      "name": "wartime-advisor",
      "source": "./plugins/wartime-advisor",
      "description": "Strategic work and leadership advisor grounded in Horowitz's Peacetime/Wartime CEO framework and Grove's strategic inflection points, plus a skill \u00d7 culture-fit talent 2x2. Direct, pushes back, diagnoses before advising.",
      "version": "1.0.0"
    },
    {
      "name": "systems-thinking",
      "source": "./plugins/systems-thinking",
      "description": "Systemic root-cause analysis via the Questions of a Systems Thinker and Causal Loop Diagrams. By Agile Pain Relief (CC BY-SA 4.0), packaged for this marketplace.",
      "version": "1.0.0"
    }
  ]
}

