  },
  "plugins": [
    {
      "name": "nerd",
      "description": "Autonomous codebase research \u2014 discovers tunable parameters, runs experiments overnight in worktrees, delivers findings with KEEP/CHANGE/INVESTIGATE recommendations",
      "version": "0.1.2",
