    {
      "name": "uav-pack",
      "source": "./plugins/uav-pack",
      "description": "UAV/drone domain pack: MAVLink-style telemetry, mission planning, embedded/edge runtime."
    },
    {
      "name": "iot-pack",
      "source": "./plugins/iot-pack",
      "description": "IoT domain pack: BLE communication, device telemetry, health-metrics processing."
    },
    {
      "name": "web-pack",
      "source": "./plugins/web-pack",
      "description": "Web/marketing domain pack: SEO, i18n, landing-page CRO, Figma-to-code styling."
    },
    {
      "name": "infra-pack",
      "source": "./plugins/infra-pack",
      "description": "Infrastructure & delivery domain pack: Kubernetes/Helm, GitOps promotion, IaC, GitLab CI, GCP CI auth, Keycloak. Opt-in; requires core."
    },
    {
      "name": "lsp-pack",
      "source": "./plugins/lsp-pack",
      "description": "Semantic code-navigation pack: Serena LSP MCP server. Opt-in; requires the serena binary (uv) on the machine."
    },
    {
      "name": "claude-eng-pack",
      "source": "./plugins/claude-eng-pack",
      "description": "Claude-engineering pack: skills for building/auditing Claude agent systems — agent architecture, tool/MCP design, prompt engineering, Claude Code config, context reliability. Opt-in; requires core."
    },
    {
      "name": "graphify-pack",
      "source": "./plugins/graphify-pack",
      "description": "Knowledge-graph pack: the /graphify skill — repo/folder → persistent knowledge graph with query/path/affected tools and HTML/JSON/Neo4j exports. Opt-in; requires the graphify CLI on the machine."
    },
    {
      "name": "architecture-pack",
      "source": "./plugins/architecture-pack",
      "description": "Repo-wide architecture map: /architecture-map generates a machine-readable JSON contract (layers, modules, file-anchored flows) + self-contained HTML viewer, freshness-stamped per commit; the swarmery dashboard serves both on its Architecture page."
    },
    {
      "name": "jira-pack",
      "source": "./plugins/jira-pack",
      "description": "Issue-tracker pack: /jira-fix drives any Jira ticket end-to-end — access preflight, defect-or-change triage, reproduction or test-first evidence, delegated fix/implementation, evidence comment, QA transition. Opt-in; requires core."
    },
    {
      "name": "accounts-pack",
      "source": "./plugins/accounts-pack",
      "description": "Multi-account pack: bind a project to one of several Claude Code accounts and run every session under it — /account, a shell wrapper, an optional shell function, and a wrong-account warning. Opt-in; requires the swarmery CLI."
    },
    {
      "name": "design-pack",
      "source": "./plugins/design-pack",
      "description": "Design-handoff pack: /design-implement takes an exported design and re-expresses it in the project's stack pixel-accurately — computed-style token inventory, reuse-vs-create recon, an approval gate, and a measured pixel diff as the completion criterion. Opt-in; requires core."
    }
  ]
}

