man:kuboon/agent-plugins:
{
  "name": "agent-plugins",
  "owner": {
    "name": "Ohkubo KOHEI",
    "email": "kuboon@gmail.com"
  },
  "metadata": {
    "description": "Claude Code plugin marketplace by kuboon."
  },
  "plugins": [
    {
      "name": "github-actions-versions",
      "source": "./plugins/github-actions-versions",
      "description": "Pin GitHub Actions to current, non-deprecated major versions when writing or editing workflows."
    },
    {
      "name": "deno-remix-init",
      "source": "./plugins/deno-remix-init",
      "description": "When initializing a new project, use Deno (not Node.js) and Remix v3 as the web framework, following the deno-remix-reference patterns."
    },
    {
      "name": "remix-ui-text-field-editable",
      "source": "./plugins/remix-ui-text-field-editable",
      "description": "When writing a freely-typed text input in @remix-run/ui (Remix v3), use defaultValue= instead of value= or it will race the framework's controlled-value reflection and become uneditable."
    },
    {
      "name": "browser-how-to",
      "source": { "source": "github", "repo": "kuboon/browser-how-to" },
      "description": "When integrating Add to Home Screen (a2hs), passkeys, or web push into a web frontend, use the @kuboon/browser-how-to library to detect support, escape in-app browsers, and guide users."
    },
    {
      "name": "github-page-preview",
      "source": "./plugins/github-page-preview",
      "description": "When deploying a static site to GitHub Pages with per-PR preview deployments, call kuboon's reusable workflow github-page-with-preview.yaml instead of hand-writing pages jobs."
    },
    {
      "name": "uint8array-base64",
      "source": "./plugins/uint8array-base64",
      "description": "For base64 (and hex) in JavaScript, use the native Uint8Array.fromBase64()/toBase64()/setFromBase64() methods instead of btoa/atob or Buffer. Works in Deno and the browser."
    },
    {
      "name": "admin-view-toggle",
      "source": "./plugins/admin-view-toggle",
      "description": "When building admin-only features, give admin users a frontend-only 一般/admin view switch that defaults to 一般, so one account can eyeball both UIs. The backend keeps authorizing as admin and never reads the toggle."
    },
    {
      "name": "deno-min-dep-age",
      "source": "./plugins/deno-min-dep-age",
      "description": "When a Deno dependency update is blocked by minimumDependencyAge, exclude the self-published @kuboon scope via minimumDependencyAge.exclude (Deno 2.9+) instead of lowering the age or passing --min-dep-age 0."
    },
    {
      "name": "remix-v3-upgrade",
      "source": "./plugins/remix-v3-upgrade",
      "description": "Upgrade a Remix v3 project across beta and rc boundaries, currently up to 3.0.0-rc.2: the @remix-run/* version table for each hop plus every breaking change, including the ones the compiler will not catch \u2014 such as ui@0.8.0 renaming every rmx-* DOM attribute to data-rmx-*."
    },
    {
      "name": "remix-db-migrations-deno",
      "source": {
        "source": "git-subdir",
        "url": "kuboon/remix-kbn",
